  if(!qaLeaseRE.test(data.lease||'')||!Number.isInteger(data.ttl)||data.ttl<60||data.ttl>604800||JSON.stringify(data.value||null).length>30000||!qaValidResponse(data.route,data.value))return response({error:'qa_value'},400);
